            if (expected_out_high === (expected_out_high ^ out_high ^ expected_out_high) &&
                expected_out_low === (expected_out_low ^ out_low ^ expected_out_low) &&
                expected_shift_db0 === (expected_shift_db0 ^ shift_db0 ^ expected_shift_db0) &&
