    // Instantiate the DUT (Device Under Test)
    SPIxIF dut (
        .Clk(Clk),
        .DAV(DAV),
        .LSB(LSB),
        .MISO(MISO),
        .Mode(Mode),
        .Rate(Rate),
        .Rst(Rst),
        .TD(TD),
        .FRE(FRE),
        .FWE(FWE),
        .MOSI(MOSI),
        .RD(RD),
        .SCK(SCK),
        .SS(SS)
    );

    // Clock generation (10ns period)
    initial begin
        Clk = 0;
        forever #5 Clk = ~Clk;
    end

        task reset_dut;

        begin
            Rst = 1;
            DAV = 0;
