    initial begin
        mclk = 0;
        forever #5 mclk = ~mclk;
    end

        task reset_dut;

        begin
            aclk_en    = 0;
            dbg_freeze = 0;
            nmi        = 1;
            nmie       = 0;
            per_addr   = 8'h00;
            per_din    = 16'h0000;
            per_en     = 0;
            per_wen    = 2'b00;
            puc        = 1;
