            @(posedge mclk);
            nmi = 0;
            @(posedge mclk);
            @(posedge mclk);
            #1;

            #1;


            check_outputs(1, 16'h6960, 0, 0, 0);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("omsp_watchdog Testbench");
        $display("========================================");


