                $display("FAIL");
                $display("  Expected: nmi_evt=%b, per_dout=%h, wdtifg_set=%b, wdtpw_error=%b, wdttmsel=%b",
                         expected_nmi_evt, expected_per_dout, expected_wdtifg_set, expected_wdtpw_error, expected_wdttmsel);
